using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using Scoreboard.Core;
namespace Scoreboard.Desktop;
public partial class GameControlWindow : Window
{
    readonly GameEngine _engine;readonly Action _publishOutput;readonly Action<bool> _setLiveScoreClock;readonly Func<bool> _getLiveScoreClock;
    public GameControlWindow(GameEngine engine,Action publishOutput,Action<bool> setLiveScoreClock,Func<bool> getLiveScoreClock){InitializeComponent();_engine=engine;_publishOutput=publishOutput;_setLiveScoreClock=setLiveScoreClock;_getLiveScoreClock=getLiveScoreClock;LiveOutputToggle.IsChecked=_getLiveScoreClock();LiveOutputToggle.Content=_getLiveScoreClock()?"Live score & clock: ON":"Live score & clock: OFF";LiveOutputStatus.Text=_getLiveScoreClock()?"LIVE SCORE/CLOCK":"MANUAL OUTPUT";_engine.Changed+=Refresh;Refresh();LiveOutputToggle.IsChecked=_getLiveScoreClock();LiveOutputToggle.Content=_getLiveScoreClock()?"Live score & clock: ON":"Live score & clock: OFF";LiveOutputStatus.Text=_getLiveScoreClock()?"LIVE SCORE/CLOCK":"MANUAL OUTPUT";}
    void Refresh(){if(!Dispatcher.CheckAccess()){Dispatcher.BeginInvoke(Refresh);return;}var s=_engine.State;HomeTitle.Text=s.HomeTeam;AwayTitle.Text=s.AwayTeam;HomeScore.Text=s.HomeScore.ToString();AwayScore.Text=s.AwayScore.ToString();HomeFouls.Text=$"Fouls: {s.HomeFouls} · Timeouts: {s.HomeTimeouts}";AwayFouls.Text=$"Fouls: {s.AwayFouls} · Timeouts: {s.AwayTimeouts}";Clock.Text=GameEngine.FormatClock(s.ClockSeconds);ClockToggle.Content=s.ClockRunning?"Stop clock":"Start clock";HomeTouchdownScore.Visibility=AwayTouchdownScore.Visibility=HomeTouchdownSubtract.Visibility=AwayTouchdownSubtract.Visibility=s.SportId=="football"?Visibility.Visible:Visibility.Collapsed;PeriodLabel.Text=$"{s.PeriodLabel} {s.Period} / {s.TotalPeriods}";FootballPanel.Visibility=s.SportId=="football"?Visibility.Visible:Visibility.Collapsed;SoccerPanel.Visibility=s.SportId=="soccer"?Visibility.Visible:Visibility.Collapsed;BaseballPanel.Visibility=s.SportId=="baseball"?Visibility.Visible:Visibility.Collapsed;BasketballPanel.Visibility=s.SportId=="basketball"?Visibility.Visible:Visibility.Collapsed;CountDisplay.Text=$"{s.Balls} balls · {s.Strikes} strikes · {s.Outs} outs";HitsDisplay.Text=$"Hits · {s.HomeTeam}: {s.HomeHits}   {s.AwayTeam}: {s.AwayHits}";DownDisplay.Text=$"{Ordinal(s.Down)} & {s.YardsToGo}";BallDisplay.Text=$"Ball at {_engine.State.YardsToGoal} yd line";CardsDisplay.Text=$"Home  🟨 {s.HomeYellowCards}   🟥 {s.HomeRedCards}       Away  🟨 {s.AwayYellowCards}   🟥 {s.AwayRedCards}";BasketballStatsDisplay.Text=$"Fouls {s.HomeTeam}: {s.HomeFouls} · {s.AwayTeam}: {s.AwayFouls}   Shot clock {s.ShotClockSeconds}s";FootballStatsDisplay.Text=$"Yards {s.HomeTeam}: {s.HomeYards} · {s.AwayTeam}: {s.AwayYards}   Turnovers {s.HomeTurnovers}–{s.AwayTurnovers}";SoccerStatsDisplay.Text=$"Shots {s.HomeShots}–{s.AwayShots}   Corners {s.HomeCorners}–{s.AwayCorners}";}
    void UpdateScore_Click(object sender,RoutedEventArgs e)=>_publishOutput();
    void LiveOutput_Changed(object sender,RoutedEventArgs e){if(LiveOutputToggle is null||LiveOutputStatus is null)return;var enabled=LiveOutputToggle.IsChecked==true;LiveOutputToggle.Content=enabled?"Live score & clock: ON":"Live score & clock: OFF";LiveOutputStatus.Text=enabled?"LIVE SCORE/CLOCK":"MANUAL OUTPUT";_setLiveScoreClock(enabled);}
    protected override void OnActivated(EventArgs e){base.OnActivated(e);if(LiveOutputToggle is null)return;LiveOutputToggle.IsChecked=_getLiveScoreClock();LiveOutputToggle.Content=_getLiveScoreClock()?"Live score & clock: ON":"Live score & clock: OFF";LiveOutputStatus.Text=_getLiveScoreClock()?"LIVE SCORE/CLOCK":"MANUAL OUTPUT";}
    static string Ordinal(int n)=>n switch{1=>"1st",2=>"2nd",3=>"3rd",_=>$"{n}th"};
    void HomeScore_Click(object s,RoutedEventArgs e)=>_engine.Score(true,ScoreAmount((Button)s));void AwayScore_Click(object s,RoutedEventArgs e)=>_engine.Score(false,ScoreAmount((Button)s));
    static int ScoreAmount(Button button)=>button.Tag?.ToString() is string tag&&tag.StartsWith("Score",StringComparison.Ordinal)&&int.TryParse(tag.AsSpan(5),out var tagged)?tagged:button.Content?.ToString()?.Replace("−","-") is string text&&int.TryParse(text,out var value)?value:0;
    void HomeTimeout_Click(object s,RoutedEventArgs e)=>_engine.Timeout(true);void AwayTimeout_Click(object s,RoutedEventArgs e)=>_engine.Timeout(false);void Possession_Click(object s,RoutedEventArgs e)=>_engine.TogglePossession();void Clock_Click(object s,RoutedEventArgs e)=>_engine.ToggleClock();void Minus_Click(object s,RoutedEventArgs e)=>_engine.AdjustClock(-60);void Plus_Click(object s,RoutedEventArgs e)=>_engine.AdjustClock(60);void MinusSecond_Click(object s,RoutedEventArgs e)=>_engine.AdjustClock(-1);void PlusSecond_Click(object s,RoutedEventArgs e)=>_engine.AdjustClock(1);void NextPeriod_Click(object s,RoutedEventArgs e)=>_engine.NextPeriod();void Undo_Click(object s,RoutedEventArgs e)=>_engine.Undo();
    void SetClock_Click(object s,RoutedEventArgs e){var d=new ControlNumberDialog("Set clock in seconds",_engine.State.ClockSeconds){Owner=this};if(d.ShowDialog()==true)_engine.SetClock(d.Value);}
    void NextDown_Click(object s,RoutedEventArgs e){if(_engine.State.Down==4&&MessageBox.Show(this,"Fourth down: start a new series and reset distance?","New series",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;_engine.AdvanceDown();}void DistanceMinus_Click(object s,RoutedEventArgs e)=>_engine.SetFootballDistance(_engine.State.YardsToGo-1);void DistancePlus_Click(object s,RoutedEventArgs e)=>_engine.SetFootballDistance(_engine.State.YardsToGo+1);void BallMinus_Click(object s,RoutedEventArgs e)=>_engine.SetFootballDistance(_engine.State.YardsToGo,Math.Min(99,_engine.State.YardsToGoal+5));void BallPlus_Click(object s,RoutedEventArgs e)=>_engine.SetFootballDistance(_engine.State.YardsToGo,Math.Max(0,_engine.State.YardsToGoal-5));void NewSeries_Click(object s,RoutedEventArgs e)=>_engine.SetFootballDistance(10);
    void HomeFoul_Click(object s,RoutedEventArgs e)=>_engine.AddFoul(true);void AwayFoul_Click(object s,RoutedEventArgs e)=>_engine.AddFoul(false);void ShotClockToggle_Click(object s,RoutedEventArgs e)=>_engine.ToggleShotClock();void ShotClockReset_Click(object s,RoutedEventArgs e)=>_engine.ResetShotClock();void ShotClockSet_Click(object s,RoutedEventArgs e){var d=new ControlNumberDialog("Set shot clock",_engine.State.ShotClockSeconds){Owner=this};if(d.ShowDialog()==true)_engine.SetShotClock(d.Value);}
    void HomeYards_Click(object s,RoutedEventArgs e)=>_engine.AddFootballYards(true,10);void AwayYards_Click(object s,RoutedEventArgs e)=>_engine.AddFootballYards(false,10);void HomeTurnover_Click(object s,RoutedEventArgs e)=>_engine.AddTurnover(true);void AwayTurnover_Click(object s,RoutedEventArgs e)=>_engine.AddTurnover(false);
    void HomeShot_Click(object s,RoutedEventArgs e)=>_engine.AddSoccerShot(true);void AwayShot_Click(object s,RoutedEventArgs e)=>_engine.AddSoccerShot(false);void HomeCorner_Click(object s,RoutedEventArgs e)=>_engine.AddSoccerCorner(true);void AwayCorner_Click(object s,RoutedEventArgs e)=>_engine.AddSoccerCorner(false);
    void BaseballBall_Click(object s,RoutedEventArgs e)=>_engine.BaseballBall();void BaseballStrike_Click(object s,RoutedEventArgs e)=>_engine.BaseballStrike();void BaseballFoul_Click(object s,RoutedEventArgs e)=>_engine.BaseballStrike(true);void BaseballOut_Click(object s,RoutedEventArgs e)=>_engine.BaseballOut();void HomeHit_Click(object s,RoutedEventArgs e)=>_engine.BaseballHit(true);void AwayHit_Click(object s,RoutedEventArgs e)=>_engine.BaseballHit(false);
    void HomeYellow_Click(object s,RoutedEventArgs e)=>_engine.AddCard(true);void AwayYellow_Click(object s,RoutedEventArgs e)=>_engine.AddCard(false);void HomeRed_Click(object s,RoutedEventArgs e)=>_engine.AddCard(true,true);void AwayRed_Click(object s,RoutedEventArgs e)=>_engine.AddCard(false,true);
    protected override void OnClosed(EventArgs e){_engine.Changed-=Refresh;base.OnClosed(e);}
}
internal sealed class ControlNumberDialog : Window
{
 readonly TextBox _input=new();public int Value=>int.TryParse(_input.Text,out var v)?Math.Max(0,v):0;
 public ControlNumberDialog(string title,int value){Title=title;Width=330;Height=170;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterOwner;var p=new StackPanel{Margin=new Thickness(15)};_input.Text=value.ToString();p.Children.Add(_input);var ok=new Button{Content="Apply",IsDefault=true,HorizontalAlignment=HorizontalAlignment.Right};ok.Click+=(_,_)=>{DialogResult=true;Close();};p.Children.Add(ok);Content=p;ThemeManager.Apply(this,PreferencesStore.Load().Theme);Loaded+=(_,_)=>_input.Focus();}
}
